<?php $tab=(string)($_GET['tab']??'topics');if(!in_array($tab,['topics','replies','articles'],true))$tab='topics';$C=community_detail_ui($locale); ?>
<section class="community-page"><div class="container community-profile"><header><?php if($member['avatar']):?><img src="<?=e($member['avatar'])?>" alt=""><?php else:?><span class="community-profile-avatar"><?=e(mb_substr((string)$member['name'],0,1,'UTF-8'))?></span><?php endif;?><div><span><?=e(community_member_badge($member,$counts['articles']))?></span><h1><?=e($member['name'])?></h1><strong>@<?=e($member['username'])?></strong><p><?=e($member['bio']?:$C['member_default'])?></p><small><?=e($C['joined'])?> <?=e(date('Y-m',strtotime($member['created_at'])))?></small></div></header><div class="community-profile-stats"><span><b><?=$counts['topics']?></b> <?=e($C['topics'])?></span><span><b><?=$counts['replies']?></b> <?=e($C['replies'])?></span><span><b><?=$counts['articles']?></b> <?=e($C['articles'])?></span></div><nav class="community-profile-tabs"><a class="<?=$tab==='topics'?'active':''?>" href="?tab=topics"><?=e($C['topic_tab'])?></a><a class="<?=$tab==='replies'?'active':''?>" href="?tab=replies"><?=e($C['reply_tab'])?></a><a class="<?=$tab==='articles'?'active':''?>" href="?tab=articles"><?=e($C['article_tab'])?></a></nav><div class="community-profile-feed"><?php if($tab==='topics'):foreach($topics as $t):?><a class="community-profile-item" href="<?=e(locale_url($locale,'community/topic/'.$t['slug']))?>"><small><?=e($t['category_name']??$C['brand'])?></small><strong><?=e($t['title'])?></strong><span><?=$t['replies_count']?> <?=e($C['replies'])?> · <?=$t['views']?> <?=e($C['views'])?></span></a><?php endforeach;elseif($tab==='replies'):foreach($replies as $r):?><a class="community-profile-item" href="<?=e(locale_url($locale,'community/topic/'.$r['slug']).'#reply-'.$r['id'])?>"><small><?=e($C['reply_in'])?> <?=e($r['title'])?></small><strong><?=e(mb_substr(trim(strip_tags((string)$r['content'])),0,180))?></strong><span><?=e(time_ago((string)$r['created_at'],$locale))?></span></a><?php endforeach;else:foreach($articles as $a):?><a class="community-profile-item" href="<?=e(locale_url($locale,'article/'.$a['slug']))?>"><small><?=e($C['article'])?></small><strong><?=e($a['title'])?></strong><span><?=e($a['excerpt'])?></span></a><?php endforeach;endif;?></div></div></section>

